const { prisma } = require('../config/database');

const {
  HTTP_STATUS,
  sendSuccess,
  handleAsync,
} = require('../utils/responseHelper');

/**
 * ============================================================================
 * SECURITY ALERT CONTROLLER
 * ============================================================================
 *
 * Returns security alerts generated by the Secure DMS backend.
 *
 * Admin:
 *   Can see all security alerts.
 *
 * Normal users:
 *   Can see alerts associated with their active cases and alerts directly
 *   associated with their own user account.
 *
 * Actual document files are never returned.
 * ============================================================================
 */

exports.getAlerts = handleAsync(
  async (req, res) => {
    const user = req.user;

    let where = {};

    /**
     * ------------------------------------------------------------------------
     * Authorization
     * ------------------------------------------------------------------------
     */

    if (user.role !== 'admin') {
      const assignments =
        await prisma.caseAssignment.findMany({
          where: {
            userId: user.id,
            status: 'active',
          },

          select: {
            caseId: true,
          },
        });

      const caseIds =
        assignments.map(
          (assignment) =>
            assignment.caseId
        );

      where = {
        OR: [
          {
            userId: user.id,
          },
          ...(caseIds.length > 0
            ? [
                {
                  caseId: {
                    in: caseIds,
                  },
                },
              ]
            : []),
        ],
      };
    }

    /**
     * ------------------------------------------------------------------------
     * Fetch alerts
     * ------------------------------------------------------------------------
     *
     * We deliberately do not restrict by status here. That keeps the API
     * useful for the security dashboard as well as the alerts page.
     * The frontend can distinguish active/resolved states.
     * ------------------------------------------------------------------------
     */

    const alerts =
      await prisma.securityAlert.findMany({
        where,

        orderBy: {
          createdAt: 'desc',
        },

        take: 500,
      });

    /**
     * ------------------------------------------------------------------------
     * Normalize response
     * ------------------------------------------------------------------------
     */

    const sanitizedAlerts =
      alerts.map(
        (alert) => ({
          id:
            alert.id,

          type:
            alert.type,

          severity:
            alert.severity,

          message:
            alert.message,

          documentId:
            alert.documentId,

          caseId:
            alert.caseId,

          userId:
            alert.userId,

          status:
            alert.status,

          metadata:
            alert.metadata,

          createdAt:
            alert.createdAt,

          updatedAt:
            alert.updatedAt,

          /*
           * Convenient frontend fields.
           */
          title:
            getAlertTitle(
              alert.type
            ),

          source:
            getAlertSource(
              alert.type
            ),
        })
      );

    return sendSuccess(
      res,
      {
        alerts:
          sanitizedAlerts,

        total:
          sanitizedAlerts.length,
      },
      HTTP_STATUS.OK
    );
  }
);

/**
 * Human-readable alert title.
 */
function getAlertTitle(type) {
  const value = String(
    type ?? ''
  )
    .trim()
    .toLowerCase();

  switch (value) {
    case 'integrity_mismatch':
      return 'Document Integrity Mismatch';

    case 'blockchain_failure':
      return 'Blockchain Anchor Failure';

    case 'unauthorized_access':
      return 'Unauthorized Access Attempt';

    case 'access_denied':
      return 'Access Denied';

    case 'account_locked':
      return 'Account Locked';

    case 'emergency_access':
      return 'Emergency Access Event';

    default:
      return String(
        type ?? 'Security Alert'
      )
        .replace(
          /_/g,
          ' '
        )
        .replace(
          /\b\w/g,
          (char) =>
            char.toUpperCase()
        );
  }
}

/**
 * Identify the broad source/category of the alert.
 */
function getAlertSource(type) {
  const value = String(
    type ?? ''
  )
    .trim()
    .toLowerCase();

  if (
    value.includes(
      'integrity'
    )
  ) {
    return 'Document Integrity';
  }

  if (
    value.includes(
      'blockchain'
    )
  ) {
    return 'Ledger';
  }

  if (
    value.includes(
      'access'
    )
  ) {
    return 'Access Control';
  }

  if (
    value.includes(
      'account'
    ) ||
    value.includes(
      'login'
    )
  ) {
    return 'Authentication';
  }

  return 'Security Monitoring';
}